# Chronology of events (type "event"). Each has at least one source link. Run: python3 archive/records/chronology.py
import json, os
F = lambda vol, d: 'https://history.state.gov/historicaldocuments/frus' + vol + '/' + d
W = lambda t: 'https://en.wikipedia.org/wiki/' + t.replace(' ', '_')
E = [
 ('1911-10-23', 'Battle and killings at Shar al-Shatt', 'Ottoman and Libyan fighters attacked the Italian lines at Shar al-Shatt (today Zawiyat al-Dahmani) three weeks into the Italian invasion; Italian troops then killed hundreds of civilians in reprisal.', ['mk-sharshatt', 'zawiyat-dahmani', 'hani'], W('Battle and massacre at Shar al-Shatt')),
 ('1911-12-04', 'Battle of Ain Zara', 'Italian forces attacked the Ottoman–Libyan positions at the Ain Zara oasis south-east of Tripoli.', ['ain-zara'], W('Battle of Ain Zara')),
 ('1945-11-04', 'Anti-Jewish riots in Tripoli', 'Riots against Tripoli’s Jewish community, under British military administration, killed more than 100 Jews; further riots followed in 1948 and 1967, after which almost all Libyan Jews left.', ['mk-riots', 'old-city'], W('1945 anti-Jewish riots in Tripolitania')),
 ('1951-12-24', 'Independence of Libya', 'Libya became an independent kingdom under King Idris; Tripoli and Benghazi were joint capitals.', ['tripoli'], W('Kingdom of Libya')),
 ('1969-09-01', 'Gaddafi’s coup', 'Junior army officers led by Captain Muammar Gaddafi seized power while King Idris was abroad, ending the monarchy. A Revolutionary Command Council took charge and declared the Libyan Arab Republic. US officials in Tripoli reported the takeover as largely bloodless.', ['tripoli', 'bab', 'palace'], F('1969-76ve05p2', 'd37')),
 ('1969-12-10', 'Abortive coup against the new regime', 'Libyan radio announced the discovery of a plot by “reactionaries”; senior officers, including ministers from the new government, were arrested.', ['tripoli'], F('1969-76ve05p2', 'd46')),
 ('1970-06-11', 'United States hands over Wheelus Air Base', 'The US left Wheelus Air Base, which became the Libyan Okba Ben Nafi air base. 11 June was celebrated afterwards as Evacuation Day.', ['wheelus', 'mitiga', 'souq-al-juma'], F('1969-76ve05p2', 'd60')),
 ('1970-10-07', 'Expulsion of Italians', 'After a July 1970 decree confiscating their property, Libya expelled its remaining Italian community, about 20,000 people. 7 October became the “Day of Revenge” holiday. The Tripoli cathedral was turned into the Gamal Abdel Nasser Mosque.', ['city-centre', 'tripoli'], W('Italian settlers in Libya')),
 ('1971-12-07', 'British Petroleum nationalised', 'Libyan radio announced the nationalisation of BP’s Libyan assets, the first of a series of takeovers of foreign oil interests.', ['tripoli'], F('1969-76ve05p2', 'd80')),
 ('1972-05-30', 'Law No. 71 criminalising party politics', 'The Revolutionary Command Council made the Arab Socialist Union the only permitted political body and set the death penalty for founding, joining or funding any group opposed to the revolution.', ['tripoli'], 'https://security-legislation.ly/?p=32378'),
 ('1973-04-15', 'Zuwara speech launches the “Cultural Revolution”', 'Gaddafi announced the suspension of existing laws, a purge of “politically sick” people and the creation of popular committees; hundreds of Islamists, Marxists, Ba’athists and other suspected opponents were arrested in the following weeks.', ['tripoli'], W('Libyan Cultural Revolution')),
 ('1976-04-07', 'Student protests crushed', 'Students at the universities in Tripoli and Benghazi protested against military control and called for elections. They were attacked by regime supporters and many were imprisoned. 7 April became a date of repression in later years.', ['fateh', 'furnaj'], W('1976 Libyan protests')),
 ('1977-03-02', 'Jamahiriya declared', 'At Sabha the General People’s Congress proclaimed the “Socialist People’s Libyan Arab Jamahiriya”, nominally government by people’s congresses and committees.', ['tripoli'], W('Libyan Arab Jamahiriya')),
 ('1977-04-07', 'Public hangings of students', 'Students were hanged in public in Benghazi; public executions were held on the 7 April anniversary in later years until the late 1980s.', ['furnaj'], W('1976 Libyan protests')),
 ('1977-07-21', 'Egyptian–Libyan border war', 'A four-day border war between Egypt and Libya followed months of tension.', ['tripoli'], W('Libyan–Egyptian war')),
 ('1979-12-02', 'US Embassy in Tripoli stormed and burned', 'A crowd of several hundred young men attacked the US Embassy in Tripoli, broke in and set it on fire; staff escaped. US officials concluded the attack had the knowledge of the highest levels of the Libyan government.', ['tripoli'], F('1977-80v17p3', 'd108')),
 ('1980-05-30', 'Campaign to eliminate opponents abroad', 'US intelligence described Gaddafi’s purges at home and the killing of exiled dissidents in Europe (the “stray dogs” campaign) in spring 1980.', ['tripoli'], F('1977-80v17p3', 'd132')),
 ('1981-08-19', 'Gulf of Sidra incident', 'US Navy jets shot down two Libyan fighters over the Gulf of Sidra, which Libya claimed as its waters.', ['tripoli'], W('Gulf of Sidra incident (1981)')),
 ('1984-04-17', 'Shooting at the Libyan People’s Bureau in London', 'Shots fired from the Libyan embassy in London at protesting exiles killed police officer Yvonne Fletcher; Britain broke off relations.', ['tripoli'], W('Murder of Yvonne Fletcher')),
 ('1984-04-23', 'Hangings in Tripoli reported', 'The Washington Post reported on public hangings in Tripoli that drew attention to Libyan dissent.', ['tripoli', 'furnaj'], 'https://www.washingtonpost.com/archive/politics/1984/04/23/hangings-in-tripoli-focus-attention-on-libyan-dissent/9c2481e3-1b2d-4b74-8d69-4304afe24ed1/'),
 ('1984-05-08', 'Armed attack on Bab al-Aziziya', 'Fighters of the exiled National Front for the Salvation of Libya attacked Gaddafi’s Bab al-Aziziya compound; the attack failed and was followed by mass arrests and executions.', ['bab'], W('National Front for the Salvation of Libya')),
 ('1984-06-05', 'Public execution of al-Sadek al-Shuwehdy', 'The engineer al-Sadek Hamed al-Shuwehdy was hanged in a Benghazi basketball stadium after a televised show trial.', ['tripoli'], W('Execution of Al-Sadek Hamed Al-Shuwehdy')),
 ('1986-01-07', 'US sanctions on Libya', 'President Reagan announced a ban on trade with Libya and ordered Americans to leave, after the Rome and Vienna airport attacks.', ['tripoli'], W('Libya–United States relations')),
 ('1986-04-15', 'US air raid on Tripoli and Benghazi', 'US aircraft bombed Bab al-Aziziya, the military side of Tripoli airport and the Sidi Bilal naval facility in Tripoli, and two targets in Benghazi, ten days after the Berlin disco bombing. Bombs also fell on homes in Ben Ashour and damaged the French embassy. Libya reported dozens of dead, including civilians.', ['as-bab', 'bab', 'as-tip', 'tip', 'as-sidibilal', 'sidibilal', 'as-benashour', 'ben-ashour', 'naval-academy'], W('1986 United States bombing of Libya')),
 ('1987-03-22', 'Defeat at Ouadi Doum in Chad', 'Chadian forces overran the main Libyan base in northern Chad, one of a string of defeats in the “Toyota War” in which thousands of Libyan soldiers, many of them conscripts, were killed or captured.', ['tripoli'], W('Toyota War')),
 ('1988-03', 'Political prisoners released', 'Gaddafi staged the release of hundreds of political prisoners; Amnesty International later reported that 426 of the 530 political prisoners in Abu Salim were released in March 1988.', ['abusalim', 'abu-salim'], W('Abu Salim prison')),
 ('1988-06-12', 'Great Green Charter of Human Rights', 'The General People’s Congress adopted a charter promising rights such as freedom from arbitrary arrest; abuses continued.', ['tripoli'], W('Human rights in Libya under Muammar Gaddafi')),
 ('1988-12-21', 'Bombing of Pan Am Flight 103 over Lockerbie', 'A bomb destroyed Pan Am 103 over Lockerbie, Scotland, killing 270 people; Libyan intelligence officers were later charged.', ['tripoli'], W('Pan Am Flight 103')),
 ('1989-09-19', 'Bombing of UTA Flight 772', 'A bomb destroyed the French airliner UTA 772 over Niger, killing 170 people; a French court later convicted six Libyans in absentia.', ['tripoli'], W('UTA Flight 772')),
 ('1992-04-15', 'UN sanctions take effect', 'UN Security Council sanctions over Lockerbie banned flights to and from Libya; Tripoli airport closed to international flights until 1999.', ['tip', 'qasr-ben-ghashir'], W('Libya–United States relations')),
 ('1996-06-29', 'Abu Salim prison massacre', 'About 1,270 prisoners were killed in Abu Salim prison after a protest over conditions. The regime did not acknowledge the deaths for years.', ['mk-abusalim', 'abusalim', 'abu-salim'], W('Abu Salim prison massacre')),
 ('2003-12-19', 'Libya gives up weapons of mass destruction', 'Libya announced it would abandon its nuclear, chemical and missile programmes, including work linked to the Tajoura centre.', ['tajoura-nuclear', 'tajura'], W('Libya and weapons of mass destruction')),
 ('2011-02-20', 'Uprising reaches Tripoli', 'Protests spread from Benghazi to Tripoli; security forces fired on protesters in Green Square and in districts such as Fashloum and Souq al-Juma.', ['green', 'fashloum', 'souq-al-juma'], W('2011 Tripoli clashes')),
 ('2011-08-20', 'Battle of Tripoli', 'An uprising inside the city and rebel forces from the west took Tripoli; Bab al-Aziziya fell on 23 August.', ['bab', 'abu-salim', 'souq-al-juma', 'salah-al-din'], W('Battle of Tripoli (2011)')),
 ('2011-08-23', 'Yarmuk massacre', 'As Tripoli fell, dozens of detainees held in a warehouse near the Khamis Brigade base south of the city were killed; their burned remains were found days later.', ['yarmouk-camp', 'salah-al-din'], W('Yarmuk massacre')),
 ('2014-07-13', 'Tripoli International Airport destroyed', 'Fighting between rival armed coalitions wrecked Tripoli International Airport.', ['tip', 'qasr-ben-ghashir'], W('Tripoli International Airport')),
 ('2016-03-30', 'Presidential Council lands at Abu Sitta', 'The UN-backed Presidential Council arrived in Tripoli by sea and set up at the Abu Sitta naval base.', ['abu-sitta-base', 'abu-sitta'], W('Libyan Navy')),
 ('2019-07-02', 'Air strike on the Tajoura detention centre', 'An air strike on a migrant detention centre in Tajoura killed more than 50 people during Haftar’s offensive on Tripoli.', ['tajura'], W('Tajoura migrant center airstrike')),
 ('2020-01-04', 'Air strike on the military college', 'An air strike killed about 30 cadets on the parade ground of the military college at al-Hadba.', ['military-college', 'hadba'], 'https://www.aljazeera.com/news/2020/1/5/dozens-killed-in-attack-on-military-academy-in-libyas-tripoli'),
 ('2020-05-23', 'Southern camps retaken', 'Government forces said they retook the Yarmouk, Sawarikh and Hamza camps from Haftar’s forces.', ['yarmouk-camp', 'artillery-school', 'hamza-camp'], 'https://www.aljazeera.com/news/2020/5/23/libya-gna-retakes-military-camps-near-tripoli'),
 ('2025-05-12', 'Killing of al-Kikli at Tekbali camp and the Tripoli clashes', 'Abdel Ghani al-Kikli (“Ghnewa”), head of the Stability Support Apparatus, was killed at a meeting at Tekbali camp; days of fighting followed in Abu Salim, Salah al-Din, Ain Zara and around the port.', ['tekbali-camp', 'abu-salim', 'salah-al-din', 'ain-zara', 'port'], W('2025 Tripoli clashes')),
 ('2025-05-19', 'Unidentified bodies and reported graves in Abu Salim', 'More than 50 unidentified bodies were found in the Abu Salim hospital morgue, and the missing-persons authority received reports of mass graves at the zoo.', ['abu-salim', 'zoo'], 'https://www.icj.org/libya-investigate-unidentified-bodies-and-reported-mass-graves-in-abu-salim/'),
 ('2026-05-18', 'Al-Senussi acquitted in the 2011 crackdown case', 'The Tripoli Court of Appeal acquitted Gaddafi’s former intelligence chief Abdullah al-Senussi in the 2011 protest-crackdown case; the 1996 Abu Salim case was still under judicial review.', ['abu-salim', 'mk-abusalim'], 'https://libyaanalysis.substack.com/p/20-may-2026-tripoli-court-sentences'),
]
out = []
for d, t, s, p, u in E:
    rid = 'ev-' + d + '-' + ''.join(c if c.isalnum() else '-' for c in t.lower())[:40].strip('-')
    src = 'Office of the Historian (FRUS)' if 'history.state.gov' in u else 'Wikipedia' if 'wikipedia.org' in u else u.split('/')[2].replace('www.', '')
    out.append({'id': rid, 'type': 'event', 'title': t, 'date': d, 'source': 'Chronology', 'source_short': 'Chronology · ' + src, 'collection': 'Tripoli: Open Source chronology', 'summary': s, 'places': p, 'link': u, 'rights': 'link-only', 'rights_note': 'Summary written for this map; follow the link for the source.', 'added': '2026-10-17'})
json.dump(out, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'chronology.json'), 'w'), ensure_ascii=False, indent=1)
print(len(out), 'events')
